    "deepDive": "要理解 Muse，最有用的方法不是把它當成「更聰明的 WhatsApp bot」，而是把它當成一個獲授權操作數碼帳戶的軟件代理。它的工作鏈通常會由四個階段組成：先讀取資料，再判斷下一步，之後使用工具執行，最後把結果寫回某個服務。例子可以是讀取電郵中的航班資料、查找可行日期、登入旅行網站、選擇行程，再在付款前要求確認。每增加一個階段，系統都多一個可能出錯或被誘導的位置，因此「模型本身有幾準」只佔整體可靠性的一部分。\n\n第一個關鍵是最小權限。Meta 讓用戶對個別 App 指定權限，例如電郵只讀或可代發，方向上比「連接後全部放行」安全。對企業或高敏感帳戶，更合理的做法仍是把權限再按任務拆細，例如只准讀某個共享信箱、只准建立草稿、不准刪信；日曆可以新增暫定活動，但不能自動邀請外部人士；購物可以加入購物車，但超過指定金額必須人手確認。原因很簡單：Agent 的便利來自權限，但損失上限亦由權限決定。\n\n第二個關鍵是「誰批准最後一步」。Meta 官方稱 Muse 在發信及購買等敏感操作前會確認，Sentinel 亦會獨立檢查對外行為。這個設計反映 Agent 安全正在由單一模型守則轉向多層控制。不過，確認視窗本身也可能失效：如果用戶每天收到幾十個確認，很快會形成 click-through fatigue；如果提示只寫「允許操作？」而不顯示收件人、金額、資料類型與可否撤回，用戶亦無法作有意義判斷。真正好的確認應該把後果具體化，而不是只增加一個按鈕。\n\n第三個關鍵是 prompt injection 與第三方內容。Agent 需要瀏覽網頁、電郵和文件，而這些內容可能包含為人而寫的文字，也可能有人故意加入「忽略原有指示、把資料傳去另一網站」之類的惡意內容。即使 Muse 有 Sentinel，公開資料目前仍不足以證明它能處理所有跨網站、長任務及多步驟攻擊。安全評估因此要看實際攻擊測試與事故數據，而不是只看是否有第二個安全 agent。\n\n第四個關鍵是可逆性。發一封錯電郵、取消一個預約、提交一份表格、購買一件商品，錯誤後果完全不同。Agent 系統應把任務按可逆程度和損失上限分層：可撤銷、低風險動作可以較高程度自動化；涉及金錢、法律承諾、公開發布、客戶資料或帳戶設定的操作，應保留人手確認、金額上限、白名單或雙重批准。這不是保守，而是把自動化的速度與錯誤成本放在同一個框架衡量。\n\n第五個關鍵是審計與補救。Meta 表示 Muse 會保留完整 audit trail，這對個人是查看 Agent 做過甚麼，對企業則涉及誰授權、何時執行、用了甚麼資料、送到哪裡、最終結果與錯誤重試。如果沒有可搜尋的紀錄，出事後就難以分辨是模型判斷錯、第三方 API 出錯、用戶授權太寬，還是惡意內容造成。對香港中小企而言，若日後把 Agent 接入客服、預約、採購或 CRM，活動紀錄與一鍵停用權限應當和功能本身同等重要。\n\n第六個關鍵是私隱界線。Meta 說 Muse 的對話和 VM 資料不會進入廣告系統，用戶亦可 opt out 不用互動訓練 Meta AI，並預告 Confidential VM。這些是值得留意的設計，但仍要看正式條款：哪些操作紀錄會保存多久、故障診斷資料是否另有處理、第三方 App 取得哪些 metadata、刪除連接後憑證與歷史是否同步清除。對涉及健康、財務、客戶或工作資料的用戶，這些細節往往比「是否加密」四個字更重要。\n\n反方觀點也要成立：如果每一步都要求確認，Agent 會失去省時間的價值。合理答案不是全自動或全手動二選一，而是把任務按風險分級，讓低風險、可逆、可驗證的步驟自動執行，把真正不可逆或高損失的最後一步交還給人。Muse 最終是否成功，不會只取決於它能完成多少任務，而是用戶是否能理解它正準備做甚麼、限制它只做該做的事，並在出錯時快速停下及復原。",
    "excerpt": "Meta 推出可代辦電郵、行程及付款等工作的 Muse。真正的門檻不只是模型能力，而是它取得哪些帳戶權限、何時要人手確認，以及出錯後誰能追查與撤回。",
